# Hypothesis: with a broad int | str overload listed first, the Literal[0] overload is shadowed, so checkers should resolve convert(0) to str and flag the shadowed overload.
from typing import Literal, TypeVar, overload, reveal_type

T = TypeVar('T')


@overload
def convert(value: int | str) -> str: ...
@overload
def convert(value: Literal[0]) -> bool: ...  # expect-error
@overload
def convert(value: list[T]) -> list[T]: ...
def convert(value: object) -> object:
    if isinstance(value, list):
        return list(value)
    return str(value)


a = convert(0)
reveal_type(a)
b = convert([1, 2])
reveal_type(b)
c = convert('hi')
reveal_type(c)
print(a, b, c)
